//! Stored profiles, declaration occurrences, and exact currency summaries.

use bigdecimal::BigDecimal;
use chrono::{DateTime, Utc};

use super::{
    funder::{Funder, FunderId},
    parliament_member::MemberId,
};

/// Latest stored member profile, not membership at the time of a payment.
#[derive(Clone, Debug)]
pub struct MemberProfile {
    /// Parliament identity.
    pub id: MemberId,
    /// Source name.
    pub name: String,
    /// Latest recorded party identity.
    pub party_id: i32,
    /// Latest recorded party name.
    pub party_name: String,
    /// Latest membership description, including constituencies and Lords memberships.
    pub membership_from: String,
    /// Current Commons membership.
    pub is_current_commons: bool,
}

/// A named funder on a declaration.
#[derive(Clone, Debug)]
pub struct FunderReference {
    /// Persistent identity.
    pub id: FunderId,
    /// Exact source name.
    pub name: String,
}

/// One source funding occurrence, including incomplete values.
#[derive(Clone, Debug)]
pub struct DeclaredFunding {
    /// Named funder when available.
    pub funder: Option<FunderReference>,
    /// Exact source amount.
    pub amount: Option<BigDecimal>,
    /// Source currency, including unknown values.
    pub currency: Option<String>,
    /// Source payment classification.
    pub payment_type: Option<String>,
}

/// A declaration with all of its funding occurrences.
#[derive(Clone, Debug)]
pub struct RecentDeclaration {
    /// Parliament declaration identity.
    pub source_id: i32,
    /// Source category.
    pub category_name: String,
    /// Registration date when available.
    pub registered_at: Option<DateTime<Utc>>,
    /// Funding occurrences, preserving duplicates.
    pub entries: Vec<DeclaredFunding>,
}

/// A member and the bounded latest declaration window.
#[derive(Clone, Debug)]
pub struct MemberDetails {
    /// Latest member profile.
    pub member: MemberProfile,
    /// Latest declarations in registration order.
    pub declarations: Vec<RecentDeclaration>,
    /// Total stored declarations.
    pub declaration_count: i64,
    /// Maximum declarations displayed.
    pub declaration_limit: usize,
}

/// Canonical funder profile with recorded names.
#[derive(Clone, Debug)]
pub struct FunderProfile {
    /// Persistent funder.
    pub funder: Funder,
    /// Company identifier with leading zeros intact.
    pub company_number: Option<String>,
    /// Every stored exact name, in stable order.
    pub aliases: Vec<String>,
}

/// Compact repository aggregate for one recipient and currency.
#[derive(Clone, Debug)]
pub struct RecipientAllocation {
    /// Latest stored recipient profile.
    pub member: MemberProfile,
    /// Source currency when recorded; unknown currencies never have totals.
    pub currency: Option<String>,
    /// Sum of known amounts, or unavailable if none are known.
    pub known_total: Option<BigDecimal>,
    /// All source occurrences.
    pub entry_count: i64,
    /// Occurrences with missing amounts.
    pub unknown_amount_count: i64,
}

/// Repository input for a consistent funder summary.
#[derive(Clone, Debug)]
pub struct FunderFunding {
    /// Persistent funder identity.
    pub profile: FunderProfile,
    /// One row per recipient and currency.
    pub allocations: Vec<RecipientAllocation>,
}

/// Support grouped by recipients' latest stored party.
#[derive(Clone, Debug)]
pub struct PartyTotal {
    /// Latest stored party identity.
    pub party_id: i32,
    /// Latest stored party name.
    pub party_name: String,
    /// Total of known amounts only.
    pub amount: Option<BigDecimal>,
    /// Funding occurrences.
    pub entry_count: i64,
    /// Occurrences with unknown amounts.
    pub unknown_amount_count: i64,
}

/// Independent totals and rankings for a single currency.
#[derive(Clone, Debug)]
pub struct CurrencyBreakdown {
    /// Source currency.
    pub currency: String,
    /// All recorded party totals.
    pub parties: Vec<PartyTotal>,
    /// Highest known totals, followed by unavailable totals if space remains.
    pub top_recipients: Vec<RecipientAllocation>,
}

/// Funder summary without currency conversion or historical party inference.
#[derive(Clone, Debug)]
pub struct FunderDetails {
    /// Persistent funder identity.
    pub profile: FunderProfile,
    /// Summaries for each known currency.
    pub currencies: Vec<CurrencyBreakdown>,
    /// All funding occurrences.
    pub entry_count: i64,
    /// Occurrences excluded because currency is unknown.
    pub unknown_currency_count: i64,
    /// Maximum recipients per currency.
    pub recipient_limit: usize,
}
//! Entity profiles and summaries from a shared exact aggregate.

mod interface;
pub use interface::EntityDetailsService;

use crate::domain::{
    models::{
        entity_details::{
            CurrencyBreakdown, FunderDetails, FunderFunding, MemberDetails, PartyTotal,
            RecipientAllocation,
        },
        funder::FunderId,
        parliament_member::MemberId,
    },
    repositories::entity_details::{EntityDetailsRepo, EntityDetailsRepoError},
};
use std::{cmp::Ordering, collections::BTreeMap};
use thiserror::Error;

const RECENT_DECLARATIONS: usize = 20;
const TOP_RECIPIENTS: usize = 10;

/// Entity detail lookup failure.
#[derive(Debug, Error)]
pub enum EntityDetailsError {
    /// No stored identity matches the request.
    #[error("entity not found")]
    NotFound,
    /// Private database diagnostics.
    #[error(transparent)]
    Unexpected(#[from] EntityDetailsRepoError),
}

/// Detail service owns summary rules and presentation limits.
#[derive(Clone)]
pub struct Service<R> {
    repo: R,
}

impl<R> Service<R> {
    /// Creates a detail service.
    #[must_use]
    pub const fn new(repo: R) -> Self {
        Self { repo }
    }
}

impl<R: EntityDetailsRepo> EntityDetailsService for Service<R> {
    async fn member(&self, id: MemberId) -> Result<MemberDetails, EntityDetailsError> {
        self.repo
            .member(id, RECENT_DECLARATIONS)
            .await?
            .ok_or(EntityDetailsError::NotFound)
    }
    async fn funder(&self, id: FunderId) -> Result<FunderDetails, EntityDetailsError> {
        self.repo
            .funder_funding(id)
            .await?
            .map(summarize_funder)
            .ok_or(EntityDetailsError::NotFound)
    }
}

fn compare_allocations(left: &RecipientAllocation, right: &RecipientAllocation) -> Ordering {
    right
        .known_total
        .cmp(&left.known_total)
        .then_with(|| left.member.id.value().cmp(&right.member.id.value()))
        .then_with(|| left.member.name.cmp(&right.member.name))
}

fn summarize_funder(funding: FunderFunding) -> FunderDetails {
    let mut entry_count = 0;
    let mut unknown_currency_count = 0;
    let mut currencies: BTreeMap<String, Vec<RecipientAllocation>> = BTreeMap::new();
    for allocation in funding.allocations {
        entry_count += allocation.entry_count;
        if let Some(currency) = &allocation.currency {
            currencies
                .entry(currency.clone())
                .or_default()
                .push(allocation);
        } else {
            unknown_currency_count += allocation.entry_count;
        }
    }
    let currencies = currencies
        .into_iter()
        .map(|(currency, mut allocations)| {
            let mut parties: BTreeMap<(i32, String), PartyTotal> = BTreeMap::new();
            for allocation in &allocations {
                let party = parties
                    .entry((
                        allocation.member.party_id,
                        allocation.member.party_name.clone(),
                    ))
                    .or_insert_with(|| PartyTotal {
                        party_id: allocation.member.party_id,
                        party_name: allocation.member.party_name.clone(),
                        amount: None,
                        entry_count: 0,
                        unknown_amount_count: 0,
                    });
                if let Some(amount) = &allocation.known_total {
                    if let Some(total) = &mut party.amount {
                        *total += amount;
                    } else {
                        party.amount = Some(amount.clone());
                    }
                }
                party.entry_count += allocation.entry_count;
                party.unknown_amount_count += allocation.unknown_amount_count;
            }
            let mut parties: Vec<_> = parties.into_values().collect();
            parties.sort_by(|left, right| {
                right
                    .amount
                    .cmp(&left.amount)
                    .then_with(|| left.party_name.cmp(&right.party_name))
                    .then_with(|| left.party_id.cmp(&right.party_id))
            });
            allocations.sort_by(compare_allocations);
            allocations.truncate(TOP_RECIPIENTS);
            CurrencyBreakdown {
                currency,
                parties,
                top_recipients: allocations,
            }
        })
        .collect();
    FunderDetails {
        profile: funding.profile,
        currencies,
        entry_count,
        unknown_currency_count,
        recipient_limit: TOP_RECIPIENTS,
    }
}
//! Consistent reads for member and funder detail views.

use crate::domain::models::{
    entity_details::{FunderFunding, MemberDetails},
    funder::FunderId,
    parliament_member::MemberId,
};
use thiserror::Error;

/// Stored entity detail reads.
pub trait EntityDetailsRepo: Clone + Send + Sync + 'static {
    /// Latest declarations for a member, or absent identity.
    fn member(
        &self,
        id: MemberId,
        recent_limit: usize,
    ) -> impl Future<Output = Result<Option<MemberDetails>, EntityDetailsRepoError>> + Send;
    /// Recipient/currency aggregates for a funder, or absent identity.
    fn funder_funding(
        &self,
        id: FunderId,
    ) -> impl Future<Output = Result<Option<FunderFunding>, EntityDetailsRepoError>> + Send;
}

/// Read failures retain private diagnostics.
#[derive(Debug, Error)]
pub enum EntityDetailsRepoError {
    /// Unexpected database or stored-data error.
    #[error("entity details read failed: {0}")]
    DatabaseError(String),
}
use crate::{
    domain::{
        models::{
            entity_details::{
                CurrencyBreakdown, DeclaredFunding, FunderDetails, FunderProfile, FunderReference,
                MemberDetails, MemberProfile, PartyTotal, RecentDeclaration, RecipientAllocation,
            },
            funder::FunderId,
            parliament_member::MemberId,
        },
        services::{
            entity_details::{EntityDetailsError, EntityDetailsService},
            entity_search::EntitySearchService,
        },
    },
    inbound::http::{error::ApiError, state::AppState, success::ApiSuccess},
};
use axum::{
    extract::{Path, State},
    http::StatusCode,
};
use chrono::{DateTime, Utc};
use serde::Serialize;

impl From<EntityDetailsError> for ApiError {
    fn from(error: EntityDetailsError) -> Self {
        match error {
            EntityDetailsError::NotFound => Self::NotFound,
            EntityDetailsError::Unexpected(_) => Self::InternalServerError,
        }
    }
}

#[derive(Serialize)]
pub struct MemberResponse {
    id: String,
    name: String,
    party_id: i32,
    party_name: String,
    membership_from: String,
    is_current_commons: bool,
}
impl From<MemberProfile> for MemberResponse {
    fn from(member: MemberProfile) -> Self {
        Self {
            id: member.id.value().to_string(),
            name: member.name,
            party_id: member.party_id,
            party_name: member.party_name,
            membership_from: member.membership_from,
            is_current_commons: member.is_current_commons,
        }
    }
}

#[derive(Serialize)]
pub struct FunderReferenceResponse {
    id: String,
    name: String,
}
impl From<FunderReference> for FunderReferenceResponse {
    fn from(funder: FunderReference) -> Self {
        Self {
            id: funder.id.value().to_string(),
            name: funder.name,
        }
    }
}

#[derive(Serialize)]
pub struct FundingResponse {
    funder: Option<FunderReferenceResponse>,
    amount: Option<String>,
    currency: Option<String>,
    payment_type: Option<String>,
}
impl From<DeclaredFunding> for FundingResponse {
    fn from(entry: DeclaredFunding) -> Self {
        Self {
            funder: entry.funder.map(Into::into),
            amount: entry
                .amount
                .map(|amount| amount.normalized().to_plain_string()),
            currency: entry.currency,
            payment_type: entry.payment_type,
        }
    }
}

#[derive(Serialize)]
pub struct DeclarationResponse {
    source_id: i32,
    category_name: String,
    registered_at: Option<DateTime<Utc>>,
    entries: Vec<FundingResponse>,
}
impl From<RecentDeclaration> for DeclarationResponse {
    fn from(declaration: RecentDeclaration) -> Self {
        Self {
            source_id: declaration.source_id,
            category_name: declaration.category_name,
            registered_at: declaration.registered_at,
            entries: declaration.entries.into_iter().map(Into::into).collect(),
        }
    }
}

#[derive(Serialize)]
pub struct MemberDetailsResponse {
    member: MemberResponse,
    declarations: Vec<DeclarationResponse>,
    declaration_count: i64,
    declaration_limit: usize,
}
impl From<MemberDetails> for MemberDetailsResponse {
    fn from(details: MemberDetails) -> Self {
        Self {
            member: details.member.into(),
            declarations: details.declarations.into_iter().map(Into::into).collect(),
            declaration_count: details.declaration_count,
            declaration_limit: details.declaration_limit,
        }
    }
}

#[derive(Serialize)]
pub struct FunderResponse {
    id: String,
    name: String,
    funder_kind: String,
    company_number: Option<String>,
    aliases: Vec<String>,
}
impl From<FunderProfile> for FunderResponse {
    fn from(profile: FunderProfile) -> Self {
        Self {
            id: profile.funder.id().value().to_string(),
            name: profile.funder.name().to_string(),
            funder_kind: profile.funder.kind().to_string(),
            company_number: profile.company_number,
            aliases: profile.aliases,
        }
    }
}

#[derive(Serialize)]
pub struct PartyTotalResponse {
    party_id: i32,
    party_name: String,
    amount: Option<String>,
    entry_count: i64,
    unknown_amount_count: i64,
}
impl From<PartyTotal> for PartyTotalResponse {
    fn from(party: PartyTotal) -> Self {
        Self {
            party_id: party.party_id,
            party_name: party.party_name,
            amount: party
                .amount
                .map(|amount| amount.normalized().to_plain_string()),
            entry_count: party.entry_count,
            unknown_amount_count: party.unknown_amount_count,
        }
    }
}

#[derive(Serialize)]
pub struct RecipientTotalResponse {
    member: MemberResponse,
    amount: Option<String>,
    entry_count: i64,
    unknown_amount_count: i64,
}
impl From<RecipientAllocation> for RecipientTotalResponse {
    fn from(recipient: RecipientAllocation) -> Self {
        Self {
            member: recipient.member.into(),
            amount: recipient
                .known_total
                .map(|amount| amount.normalized().to_plain_string()),
            entry_count: recipient.entry_count,
            unknown_amount_count: recipient.unknown_amount_count,
        }
    }
}

#[derive(Serialize)]
pub struct CurrencyResponse {
    currency: String,
    parties: Vec<PartyTotalResponse>,
    top_recipients: Vec<RecipientTotalResponse>,
}
impl From<CurrencyBreakdown> for CurrencyResponse {
    fn from(group: CurrencyBreakdown) -> Self {
        Self {
            currency: group.currency,
            parties: group.parties.into_iter().map(Into::into).collect(),
            top_recipients: group.top_recipients.into_iter().map(Into::into).collect(),
        }
    }
}

#[derive(Serialize)]
pub struct FunderDetailsResponse {
    funder: FunderResponse,
    currencies: Vec<CurrencyResponse>,
    entry_count: i64,
    unknown_currency_count: i64,
    recipient_limit: usize,
}
impl From<FunderDetails> for FunderDetailsResponse {
    fn from(details: FunderDetails) -> Self {
        Self {
            funder: details.profile.into(),
            currencies: details.currencies.into_iter().map(Into::into).collect(),
            entry_count: details.entry_count,
            unknown_currency_count: details.unknown_currency_count,
            recipient_limit: details.recipient_limit,
        }
    }
}

pub async fn member_details<E: EntitySearchService, D: EntityDetailsService>(
    State(state): State<AppState<E, D>>,
    Path(id): Path<String>,
) -> Result<ApiSuccess<MemberDetailsResponse>, ApiError> {
    let id = id
        .parse::<MemberId>()
        .map_err(|error| ApiError::UnprocessibleEntity(error.to_string()))?;
    let details = state.entity_details_service.member(id).await?;
    Ok(ApiSuccess::new(StatusCode::OK, details.into()))
}

pub async fn funder_details<E: EntitySearchService, D: EntityDetailsService>(
    State(state): State<AppState<E, D>>,
    Path(id): Path<String>,
) -> Result<ApiSuccess<FunderDetailsResponse>, ApiError> {
    let id = id
        .parse::<FunderId>()
        .map_err(|_| ApiError::UnprocessibleEntity("Invalid funder ID".into()))?;
    let details = state.entity_details_service.funder(id).await?;
    Ok(ApiSuccess::new(StatusCode::OK, details.into()))
}
use crate::{
    domain::{
        models::{
            entity_details::{
                DeclaredFunding, FunderFunding, FunderProfile, FunderReference, MemberDetails,
                MemberProfile, RecentDeclaration, RecipientAllocation,
            },
            funder::{Funder, FunderId, FunderKind},
            parliament_member::MemberId,
        },
        repositories::entity_details::{EntityDetailsRepo, EntityDetailsRepoError},
    },
    outbound::postgres::ExposedDatabase,
};
use std::str::FromStr;

const CURRENCY_WHITESPACE: &str = "\t\n\u{000b}\u{000c}\r \u{0085}\u{00a0}\u{1680}\u{2000}\u{2001}\u{2002}\u{2003}\u{2004}\u{2005}\u{2006}\u{2007}\u{2008}\u{2009}\u{200a}\u{2028}\u{2029}\u{202f}\u{205f}\u{3000}\u{feff}";

impl EntityDetailsRepo for ExposedDatabase {
    async fn member(
        &self,
        id: MemberId,
        recent_limit: usize,
    ) -> Result<Option<MemberDetails>, EntityDetailsRepoError> {
        let mut tx = self.pool().begin().await?;
        sqlx::query!("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
            .execute(&mut *tx)
            .await?;
        let row = sqlx::query!(
            "SELECT parliament_member_id, name, party_id, party_name, latest_membership_from, is_current_commons,
                (SELECT count(*) FROM exposed.declarations d WHERE d.member_id = m.id) AS \"declaration_count!\"
             FROM exposed.members m WHERE parliament_member_id = $1", i32::try_from(id.value()).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?
        ).fetch_optional(&mut *tx).await?;
        let Some(row) = row else {
            return Ok(None);
        };
        let member = MemberProfile {
            id,
            name: row.name,
            party_id: row.party_id,
            party_name: row.party_name,
            membership_from: row.latest_membership_from,
            is_current_commons: row.is_current_commons,
        };
        let rows = sqlx::query!(
            "WITH recent AS (
                SELECT d.source_declaration_id, d.category_name, d.registration_date
                FROM exposed.declarations d JOIN exposed.members m ON m.id = d.member_id
                WHERE m.parliament_member_id = $1
                ORDER BY d.registration_date DESC NULLS LAST, d.source_declaration_id DESC LIMIT $2
             )
             SELECT d.source_declaration_id, d.category_name, d.registration_date,
                e.id AS \"entry_id?\", e.amount, e.currency, e.payment_type, f.id AS \"funder_id?\", f.funder_name AS \"funder_name?\"
             FROM recent d LEFT JOIN exposed.funding_entries e ON e.source_declaration_id = d.source_declaration_id
             LEFT JOIN exposed.funders f ON f.id = e.funder_id
             ORDER BY d.registration_date DESC NULLS LAST, d.source_declaration_id DESC, e.id",
             i32::try_from(id.value()).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?,
             i64::try_from(recent_limit).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?
        ).fetch_all(&mut *tx).await?;
        let mut declarations: Vec<RecentDeclaration> = Vec::new();
        for row in rows {
            if declarations
                .last()
                .is_none_or(|declaration| declaration.source_id != row.source_declaration_id)
            {
                declarations.push(RecentDeclaration {
                    source_id: row.source_declaration_id,
                    category_name: row.category_name,
                    registered_at: row
                        .registration_date
                        .map(|date| {
                            chrono::DateTime::from_timestamp(
                                date.unix_timestamp(),
                                date.nanosecond(),
                            )
                            .ok_or_else(|| {
                                EntityDetailsRepoError::DatabaseError(
                                    "Stored registration date is out of range".into(),
                                )
                            })
                        })
                        .transpose()?,
                    entries: Vec::new(),
                });
            }
            if row.entry_id.is_some() {
                let funder = row
                    .funder_id
                    .zip(row.funder_name)
                    .map(|(id, name)| FunderReference {
                        id: FunderId::new(id),
                        name,
                    });
                if let Some(declaration) = declarations.last_mut() {
                    declaration.entries.push(DeclaredFunding {
                        funder,
                        amount: row.amount,
                        currency: row.currency,
                        payment_type: row.payment_type,
                    });
                }
            }
        }
        tx.commit().await?;
        Ok(Some(MemberDetails {
            member,
            declarations,
            declaration_count: row.declaration_count,
            declaration_limit: recent_limit,
        }))
    }

    async fn funder_funding(
        &self,
        id: FunderId,
    ) -> Result<Option<FunderFunding>, EntityDetailsRepoError> {
        let mut tx = self.pool().begin().await?;
        sqlx::query!("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
            .execute(&mut *tx)
            .await?;
        let row = sqlx::query!(
            "SELECT funder_name, funder_kind, company_number FROM exposed.funders WHERE id = $1",
            id.value()
        )
        .fetch_optional(&mut *tx)
        .await?;
        let Some(row) = row else {
            return Ok(None);
        };
        let kind = row
            .funder_kind
            .as_deref()
            .map_or(Ok(FunderKind::NotSpecified), FunderKind::from_str)
            .map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?;
        let aliases = sqlx::query_scalar!(
            "SELECT funder_alias FROM exposed.funder_aliases WHERE funder_id = $1 ORDER BY funder_alias COLLATE \"C\"",
            id.value()
        )
        .fetch_all(&mut *tx)
        .await?;
        let profile = FunderProfile {
            funder: Funder::new(id, row.funder_name, kind),
            company_number: row.company_number,
            aliases,
        };
        let rows = sqlx::query!(
            "WITH funding AS (
                SELECT source_declaration_id, amount, NULLIF(btrim(currency, $2), '') AS currency
                FROM exposed.funding_entries WHERE funder_id = $1
             )
             SELECT m.parliament_member_id, m.name, m.party_id, m.party_name, m.latest_membership_from, m.is_current_commons,
                e.currency,
                CASE WHEN e.currency IS NOT NULL THEN sum(e.amount) END AS known_total,
                count(*) AS \"entry_count!\", count(*) FILTER (WHERE e.amount IS NULL) AS \"unknown_amount_count!\"
             FROM funding e JOIN exposed.declarations d ON d.source_declaration_id = e.source_declaration_id
             JOIN exposed.members m ON m.id = d.member_id
             GROUP BY m.id, e.currency
             ORDER BY m.parliament_member_id, currency NULLS LAST", id.value(), CURRENCY_WHITESPACE
        ).fetch_all(&mut *tx).await?;
        let allocations = rows
            .into_iter()
            .map(|row| {
                let id = row
                    .parliament_member_id
                    .to_string()
                    .parse::<MemberId>()
                    .map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?;
                Ok(RecipientAllocation {
                    member: MemberProfile {
                        id,
                        name: row.name,
                        party_id: row.party_id,
                        party_name: row.party_name,
                        membership_from: row.latest_membership_from,
                        is_current_commons: row.is_current_commons,
                    },
                    currency: row.currency,
                    known_total: row.known_total,
                    entry_count: row.entry_count,
                    unknown_amount_count: row.unknown_amount_count,
                })
            })
            .collect::<Result<Vec<_>, EntityDetailsRepoError>>()?;
        tx.commit().await?;
        Ok(Some(FunderFunding {
            profile,
            allocations,
        }))
    }
}

